package io.romgold.aquoswireless;
import android.content.Context; import android.content.Intent; import android.media.AudioManager; import android.net.Uri; import android.content.pm.PackageManager; import android.content.pm.ResolveInfo; import androidx.core.content.FileProvider; import fi.iki.elonen.NanoHTTPD; import org.json.JSONArray; import org.json.JSONObject; import java.io.File; import java.io.FileOutputStream; import java.io.InputStream; import java.util.List; import java.util.Map;
public class LocalWebServer extends NanoHTTPD {
 private final Context c; LocalWebServer(Context c){super("0.0.0.0",8765);this.c=c.getApplicationContext();}
 @Override public Response serve(IHTTPSession s){try{String u=s.getUri();
  if(Method.GET.equals(s.getMethod())&&("/".equals(u)||"/index.html".equals(u)))return newChunkedResponse(Response.Status.OK,"text/html; charset=utf-8",c.getAssets().open("index.html"));
  if(Method.GET.equals(s.getMethod())&&"/apps".equals(u))return json(apps());
  if(Method.GET.equals(s.getMethod())&&"/action".equals(u))return json(new JSONObject().put("ok",control(s.getParms().get("name"))));
  if(Method.GET.equals(s.getMethod())&&"/launch".equals(u)){String p=s.getParms().get("pkg");Intent i=c.getPackageManager().getLeanbackLaunchIntentForPackage(p);if(i==null)i=c.getPackageManager().getLaunchIntentForPackage(p);if(i==null)return json(new JSONObject().put("ok",false).put("error","Приложение не найдено"));i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);c.startActivity(i);return json(new JSONObject().put("ok",true));}
  if(Method.POST.equals(s.getMethod())&&"/text".equals(u)){Map<String,String>b=new java.util.HashMap<>();s.parseBody(b);String t=b.get("text");boolean ok=RemoteAccessibilityService.instance!=null&&RemoteAccessibilityService.instance.typeText(t==null?"":t);return json(new JSONObject().put("ok",ok));}
  if(Method.POST.equals(s.getMethod())&&"/upload".equals(u))return upload(s);
  return newFixedLengthResponse(Response.Status.NOT_FOUND,"text/plain","Not found");
 }catch(Exception e){return newFixedLengthResponse(Response.Status.INTERNAL_ERROR,"text/plain; charset=utf-8",e.toString());}}
 private boolean control(String n){if("volup".equals(n)||"voldown".equals(n)){AudioManager a=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);a.adjustStreamVolume(AudioManager.STREAM_MUSIC,"volup".equals(n)?AudioManager.ADJUST_RAISE:AudioManager.ADJUST_LOWER,0);return true;}RemoteAccessibilityService x=RemoteAccessibilityService.instance;return x!=null&&x.action(n);}
 private JSONObject apps()throws Exception{JSONArray a=new JSONArray();Intent q=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LEANBACK_LAUNCHER);PackageManager p=c.getPackageManager();List<ResolveInfo> l=p.queryIntentActivities(q,0);for(ResolveInfo r:l)a.put(new JSONObject().put("package",r.activityInfo.packageName).put("name",r.loadLabel(p).toString()));return new JSONObject().put("apps",a);}
 private Response upload(IHTTPSession s)throws Exception{Map<String,String> f=new java.util.HashMap<>();s.parseBody(f);String tmp=f.get("file");if(tmp==null)return json(new JSONObject().put("ok",false).put("error","Файл не получен"));File src=new File(tmp),dir=new File(c.getCacheDir(),"incoming");if(!dir.exists())dir.mkdirs();String n=s.getParms().get("name");if(n==null)n=src.getName();n=n.replaceAll("[^a-zA-Z0-9._-]","_");File dst=new File(dir,System.currentTimeMillis()+"_"+n);try(InputStream in=new java.io.FileInputStream(src);FileOutputStream out=new FileOutputStream(dst)){byte[] b=new byte[65536];int k;while((k=in.read(b))>0)out.write(b,0,k);}String mime=n.toLowerCase().matches(".*\\.(jpg|jpeg|png|webp|gif)$")?"image/*":"video/*";Uri uri=FileProvider.getUriForFile(c,"io.romgold.aquoswireless.files",dst);Intent v=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,mime).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_GRANT_READ_URI_PERMISSION);c.startActivity(v);return json(new JSONObject().put("ok",true).put("message","Открываем на телевизоре"));}
 private Response json(JSONObject o){return newFixedLengthResponse(Response.Status.OK,"application/json; charset=utf-8",o.toString());}
}
